#!/bin/bash
# usage: gen3.sh <logname> "<numbered image list>"  — ready-to-wear reshoot for Cathedral II
cd "$(dirname "$0")"
codex exec --skip-git-repo-check --sandbox workspace-write "Use your built-in image generation tool (not the CLI fallback) to generate the following separate images, one at a time, and save them as PNG in assets/img/cathedral/ with exactly these names (overwrite existing files). These are campaign and e-commerce photographs for a premium READY-TO-WEAR women's corset brand (think House of CB, Agent Provocateur, Miaou, Reformation campaign quality) — NOT couture, NOT costume, NOT period drama. Models are adult women of varied ethnicity and body type, in contemporary everyday-luxe styling: the corset is worn as a modern top or layering piece with jeans, tailored trousers, blazers, crisp shirts, slip skirts, knitwear, modern jewellery, natural modern hair and makeup. The corsets themselves are clean, production-quality garments: smooth panels, neat topstitched boning channels, minimal decoration, no heavy embroidery, no ball gowns, no tulle, no candelabras, no historical costume. Setting and light keep a subtle gothic mood so they fit a dark website: a dark plaster or stone studio wall with a single pointed-arch window shape or arch shadow, or a city street by old stone architecture at dusk, lit with soft directional light plus a wash of coloured gel light matching the corset (as if from stained glass). Dark, moody, rich colour, sharp fashion photography, shallow depth of field, corset clearly visible from bust to hip in the centre of the frame. No text, no logos, no watermarks.
$2
After saving all of them, list the files." < /dev/null > "logs/$1.log" 2>&1
echo "done $1"
